terraform {
  required_version = ">= 1.17.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "6.73.0"
    }
  }
}

provider "aws" {
  region = "eu-west-2"
}

# Buyer names, emails and payment references. Must never be public.
resource "aws_s3_bucket" "buyer_records" {
  bucket = "tallowmark-prod-buyer-records"
}

resource "aws_s3_bucket_versioning" "buyer_records" {
  bucket = "tallowmark-prod-buyer-records"
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "buyer_records" {
  bucket                  = "tallowmark-prod-buyer-records"
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

module "scan_store" {
  source = "../../modules/scan-store"
  env    = "prod"
}
# Door scanner readings from every show land in this queue, then in this bucket.
# The lifecycle rule that expired old readings used to live here.

variable "env" {
  type = string
}

resource "aws_sqs_queue" "scan" {
  name                      = "tallowmark-scan-readings"
  message_retention_seconds = 345600
}

resource "aws_s3_bucket" "scan" {
  bucket = "tallowmark-scan-archive"
}

